function detectPrototypePollution(input) {
    try {
        // 创建一个沙箱环境
        const sandbox = {
            Object: Object
        };

        // 尝试执行恶意代码
        vm.createContext(sandbox);
        const script = new vm.Script(input);
        script.runInContext(sandbox);

        // 检查是否污染了 Object.prototype
        if (sandbox.Object.prototype.constructor === Object.prototype.constructor) {
            return false; // 未被污染
        } else {
            return true; // 存在污染
        }
    } catch (e) {
        return false; // 执行出错，不视为漏洞
    }
}

// 读取文件并检测
